insert into public.verses (no, track, chapter, topic, ref, ref_short, ref_full, text, week, is_active)
values
  (2001, 'navi', 'assurance', '구원의 확신', '요일 5:11-12', '요일 5:11-12', '요한일서 5장 11-12절', '또 증거는 이것이니 하나님이 우리에게 영생을 주신 것과 이 생명이 그의 아들 안에 있는 그것이니라 아들이 있는 자에게는 생명이 있고 하나님의 아들이 없는 자에게는 생명이 없느니라', null, true),
  (2002, 'navi', 'assurance', '기도 응답의 확신', '요 16:24', '요 16:24', '요한복음 16장 24절', '지금까지는 너희가 내 이름으로 아무 것도 구하지 아니하였으나 구하라 그리하면 받으리니 너희 기쁨이 충만하리라', null, true),
  (2003, 'navi', 'assurance', '승리의 확신', '고전 10:13', '고전 10:13', '고린도전서 10장 13절', '사람이 감당할 시험 밖에는 너희가 당한 것이 없나니 오직 하나님은 미쁘사 너희가 감당하지 못할 시험 당함을 허락하지 아니하시고 시험 당할 즈음에 또한 피할 길을 내사 너희로 능히 감당하게 하시느니라', null, true),
  (2004, 'navi', 'assurance', '사죄의 확신', '요일 1:9', '요일 1:9', '요한일서 1장 9절', '만일 우리가 우리 죄를 자백하면 그는 미쁘시고 의로우사 우리 죄를 사하시며 우리를 모든 불의에서 깨끗하게 하실 것이요', null, true),
  (2005, 'navi', 'assurance', '인도의 확신', '잠 3:5-6', '잠 3:5-6', '잠언 3장 5-6절', '너는 마음을 다하여 여호와를 신뢰하고 네 명철을 의지하지 말라 너는 범사에 그를 인정하라 그리하면 네 길을 지도하시리라', null, true),
  (2011, 'navi', 'guide', '그리스도 안의 생활', '요 15:5', '요 15:5', '요한복음 15장 5절', '나는 포도나무요 너희는 가지라 그가 내 안에 내가 그 안에 거하면 사람이 열매를 많이 맺나니 나를 떠나서는 너희가 아무 것도 할 수 없음이라', null, true),
  (2012, 'navi', 'guide', '하나님의 말씀에 의한 생활', '행 20:32', '행 20:32', '사도행전 20장 32절', '지금 내가 여러분을 주와 및 그 은혜의 말씀에 부탁하노니 그 말씀이 여러분을 능히 든든히 세우사 거룩하게 하심을 입은 모든 자 가운데 기업이 있게 하시리라', null, true),
  (2013, 'navi', 'guide', '하나님의 성령에 의한 생활', '롬 8:14', '롬 8:14', '로마서 8장 14절', '무릇 하나님의 영으로 인도함을 받는 사람은 곧 하나님의 아들이라', null, true),
  (2014, 'navi', 'guide', '믿음에 의한 생활', '고후 5:7', '고후 5:7', '고린도후서 5장 7절', '이는 우리가 믿음으로 행하고 보는 것으로 행하지 아니함이로라', null, true),
  (2015, 'navi', 'guide', '사랑에 의한 생활', '요일 4:11', '요일 4:11', '요한일서 4장 11절', '사랑하는 자들아 하나님이 이같이 우리를 사랑하셨은즉 우리도 서로 사랑하는 것이 마땅하도다', null, true),
  (2016, 'navi', 'guide', '그리스도인의 교제하는 생활', '요일 1:7', '요일 1:7', '요한일서 1장 7절', '그가 빛 가운데 계신 것 같이 우리도 빛 가운데 행하면 우리가 서로 사귐이 있고 그 아들 예수의 피가 우리를 모든 죄에서 깨끗하게 하실 것이요', null, true),
  (2017, 'navi', 'guide', '증인으로서의 생활', '벧전 3:15', '벧전 3:15', '베드로전서 3장 15절', '너희 마음에 그리스도를 주로 삼아 거룩하게 하고 너희 속에 있는 소망에 관한 이유를 묻는 자에게는 대답할 것을 항상 준비하되 온유와 두려움으로 하고', null, true),
  (2018, 'navi', 'guide', '후히 드리는 생활', '고후 9:7', '고후 9:7', '고린도후서 9장 7절', '각각 그 마음에 정한 대로 할 것이요 인색함으로나 억지로 하지 말지니 하나님은 즐겨 내는 자를 사랑하시느니라', null, true),
  (2021, 'navi', 'A', '중심되신 그리스도', '고후 5:17', '고후 5:17', '고린도후서 5장 17절', '그런즉 누구든지 그리스도 안에 있으면 새로운 피조물이라 이전 것은 지나갔으니 보라 새 것이 되었도다', null, true),
  (2022, 'navi', 'A', '중심되신 그리스도', '갈 2:20', '갈 2:20', '갈라디아서 2장 20절', '내가 그리스도와 함께 십자가에 못 박혔나니 그런즉 이제는 내가 사는 것이 아니요 오직 내 안에 그리스도께서 사시는 것이라 이제 내가 육체 가운데 사는 것은 나를 사랑하사 나를 위하여 자기 자신을 버리신 하나님의 아들을 믿는 믿음 안에서 사는 것이라', null, true),
  (2023, 'navi', 'A', '그리스도께 순종', '롬 12:1', '롬 12:1', '로마서 12장 1절', '그러므로 형제들아 내가 하나님의 모든 자비하심으로 너희를 권하노니 너희 몸을 하나님이 기뻐하시는 거룩한 산 제물로 드리라 이는 너희가 드릴 영적 예배니라', null, true),
  (2024, 'navi', 'A', '그리스도께 순종', '요 14:21', '요 14:21', '요한복음 14장 21절', '나의 계명을 지키는 자라야 나를 사랑하는 자니 나를 사랑하는 자는 내 아버지께 사랑을 받을 것이요 나도 그를 사랑하여 그에게 나를 나타내리라', null, true),
  (2025, 'navi', 'A', '말씀', '딤후 3:16', '딤후 3:16', '디모데후서 3장 16절', '모든 성경은 하나님의 감동으로 된 것으로 교훈과 책망과 바르게 함과 의로 교육하기에 유익하니', null, true),
  (2026, 'navi', 'A', '말씀', '수 1:8', '수 1:8', '여호수아 1장 8절', '이 율법책을 네 입에서 떠나지 말게 하며 주야로 그것을 묵상하여 그 안에 기록된 대로 다 지켜 행하라 그리하면 네 길이 평탄하게 될 것이며 네가 형통하리라', null, true),
  (2027, 'navi', 'A', '기도', '요 15:7', '요 15:7', '요한복음 15장 7절', '너희가 내 안에 거하고 내 말이 너희 안에 거하면 무엇이든지 원하는 대로 구하라 그리하면 이루리라', null, true),
  (2028, 'navi', 'A', '기도', '빌 4:6-7', '빌 4:6-7', '빌립보서 4장 6-7절', '아무 것도 염려하지 말고 다만 모든 일에 기도와 간구로 너희 구할 것을 감사함으로 하나님께 아뢰라 그리하면 모든 지각에 뛰어난 하나님의 평강이 그리스도 예수 안에서 너희 마음과 생각을 지키시리라', null, true),
  (2029, 'navi', 'A', '교제', '마 18:20', '마 18:20', '마태복음 18장 20절', '두세 사람이 내 이름으로 모인 곳에는 나도 그들 중에 있느니라', null, true),
  (2030, 'navi', 'A', '교제', '히 10:24-25', '히 10:24-25', '히브리서 10장 24-25절', '서로 돌아보아 사랑과 선행을 격려하며 모이기를 폐하는 어떤 사람들의 습관과 같이 하지 말고 오직 권하여 그 날이 가까움을 볼수록 더욱 그리하자', null, true),
  (2031, 'navi', 'A', '증거', '마 4:19', '마 4:19', '마태복음 4장 19절', '말씀하시되 나를 따라오라 내가 너희를 사람을 낚는 어부가 되게 하리라 하시니', null, true),
  (2032, 'navi', 'A', '증거', '롬 1:16', '롬 1:16', '로마서 1장 16절', '내가 복음을 부끄러워하지 아니하노니 이 복음은 모든 믿는 자에게 구원을 주시는 하나님의 능력이 됨이라 먼저는 유대인에게요 그리고 헬라인에게로다', null, true),
  (2041, 'navi', 'B', '모든 사람이 죄를 범함', '롬 3:23', '롬 3:23', '로마서 3장 23절', '모든 사람이 죄를 범하였으매 하나님의 영광에 이르지 못하더니', null, true),
  (2042, 'navi', 'B', '모든 사람이 죄를 범함', '사 53:6', '사 53:6', '이사야 53장 6절', '우리는 다 양 같아서 그릇 행하여 각기 제 길로 갔거늘 여호와께서는 우리 모두의 죄악을 그에게 담당시키셨도다', null, true),
  (2043, 'navi', 'B', '죄의 형벌', '롬 6:23', '롬 6:23', '로마서 6장 23절', '죄의 삯은 사망이요 하나님의 은사는 그리스도 예수 우리 주 안에 있는 영생이니라', null, true),
  (2044, 'navi', 'B', '죄의 형벌', '히 9:27', '히 9:27', '히브리서 9장 27절', '한 번 죽는 것은 사람에게 정해진 것이요 그 후에는 심판이 있으리니', null, true),
  (2045, 'navi', 'B', '그리스도가 형벌을 받음', '롬 5:8', '롬 5:8', '로마서 5장 8절', '우리가 아직 죄인 되었을 때에 그리스도께서 우리를 위하여 죽으심으로 하나님께서 우리에 대한 자기의 사랑을 확증하셨느니라', null, true),
  (2046, 'navi', 'B', '그리스도가 형벌을 받음', '벧전 3:18', '벧전 3:18', '베드로전서 3장 18절', '그리스도께서도 단번에 죄를 위하여 죽으사 의인으로서 불의한 자를 대신하셨으니 이는 우리를 하나님 앞으로 인도하려 하심이라 육체로는 죽임을 당하시고 영으로는 살리심을 받으셨으니', null, true),
  (2047, 'navi', 'B', '선행으로 구원받지 못함', '엡 2:8-9', '엡 2:8-9', '에베소서 2장 8-9절', '너희는 그 은혜에 의하여 믿음으로 말미암아 구원을 받았으니 이것은 너희에게서 난 것이 아니요 하나님의 선물이라 행위에서 난 것이 아니니 이는 누구든지 자랑하지 못하게 함이라', null, true),
  (2048, 'navi', 'B', '선행으로 구원받지 못함', '딛 3:5', '딛 3:5', '디도서 3장 5절', '우리를 구원하시되 우리가 행한 바 의로운 행위로 말미암지 아니하고 오직 그의 긍휼하심을 따라 중생의 씻음과 성령의 새롭게 하심으로 하셨나니', null, true),
  (2049, 'navi', 'B', '그리스도를 모셔야 함', '요 1:12', '요 1:12', '요한복음 1장 12절', '영접하는 자 곧 그 이름을 믿는 자들에게는 하나님의 자녀가 되는 권세를 주셨으니', null, true),
  (2050, 'navi', 'B', '그리스도를 모셔야 함', '계 3:20', '계 3:20', '요한계시록 3장 20절', '볼지어다 내가 문 밖에 서서 두드리노니 누구든지 내 음성을 듣고 문을 열면 내가 그에게로 들어가 그와 더불어 먹고 그는 나와 더불어 먹으리라', null, true),
  (2051, 'navi', 'B', '구원의 확신', '요일 5:13', '요일 5:13', '요한일서 5장 13절', '내가 하나님의 아들의 이름을 믿는 너희에게 이것을 쓰는 것은 너희로 하여금 너희에게 영생이 있음을 알게 하려 함이라', null, true),
  (2052, 'navi', 'B', '구원의 확신', '요 5:24', '요 5:24', '요한복음 5장 24절', '내가 진실로 진실로 너희에게 이르노니 내 말을 듣고 또 나 보내신 이를 믿는 자는 영생을 얻었고 심판에 이르지 아니하나니 사망에서 생명으로 옮겼느니라', null, true),
  (2061, 'navi', 'C', '성령', '고전 3:16', '고전 3:16', '고린도전서 3장 16절', '너희는 너희가 하나님의 성전인 것과 하나님의 성령이 너희 안에 계시는 것을 알지 못하느냐', null, true),
  (2062, 'navi', 'C', '성령', '고전 2:12', '고전 2:12', '고린도전서 2장 12절', '우리가 세상의 영을 받지 아니하고 오직 하나님으로부터 온 영을 받았으니 이는 우리로 하여금 하나님께서 우리에게 은혜로 주신 것들을 알게 하려 하심이라', null, true),
  (2063, 'navi', 'C', '능력', '사 41:10', '사 41:10', '이사야 41장 10절', '두려워하지 말라 내가 너와 함께 함이라 놀라지 말라 나는 네 하나님이 됨이라 내가 너를 굳세게 하리라 참으로 너를 도와 주리라 참으로 나의 의로운 오른손으로 너를 붙들리라', null, true),
  (2064, 'navi', 'C', '능력', '빌 4:13', '빌 4:13', '빌립보서 4장 13절', '내게 능력 주시는 자 안에서 내가 모든 것을 할 수 있느니라', null, true),
  (2065, 'navi', 'C', '성실', '애 3:22-23', '애 3:22-23', '예레미야애가 3장 22-23절', '여호와의 인자와 긍휼이 무궁하시므로 우리가 진멸되지 아니함이니이다 이것들이 아침마다 새로우니 주의 성실하심이 크시도소이다', null, true),
  (2066, 'navi', 'C', '성실', '민 23:19', '민 23:19', '민수기 23장 19절', '하나님은 사람이 아니시니 거짓말을 하지 않으시고 인생이 아니시니 후회가 없으시도다 어찌 그 말씀하신 바를 행하지 않으시며 하신 말씀을 실행하지 않으시랴', null, true),
  (2067, 'navi', 'C', '평안', '사 26:3', '사 26:3', '이사야 26장 3절', '주께서 심지가 견고한 자를 평강하고 평강하도록 지키시리니 이는 그가 주를 신뢰함이니이다', null, true),
  (2068, 'navi', 'C', '평안', '벧전 5:7', '벧전 5:7', '베드로전서 5장 7절', '너희 염려를 다 주께 맡기라 이는 그가 너희를 돌보심이라', null, true),
  (2069, 'navi', 'C', '공급', '롬 8:32', '롬 8:32', '로마서 8장 32절', '자기 아들을 아끼지 아니하시고 우리 모든 사람을 위하여 내주신 이가 어찌 그 아들과 함께 모든 것을 우리에게 주시지 아니하겠느냐', null, true),
  (2070, 'navi', 'C', '공급', '빌 4:19', '빌 4:19', '빌립보서 4장 19절', '나의 하나님이 그리스도 예수 안에서 영광 가운데 그 풍성한 대로 너희 모든 쓸 것을 채우시리라', null, true),
  (2071, 'navi', 'C', '유혹에서 도우심', '히 2:18', '히 2:18', '히브리서 2장 18절', '그가 시험을 받아 고난을 당하셨은즉 시험 받는 자들을 능히 도우실 수 있느니라', null, true),
  (2072, 'navi', 'C', '유혹에서 도우심', '시 119:9, 11', '시 119:9, 11', '시편 119편 9, 11절', '청년이 무엇으로 그의 행실을 깨끗하게 하리이까 주의 말씀만 지킬 따름이니이다 내가 주께 범죄하지 아니하려 하여 주의 말씀을 내 마음에 두었나이다', null, true),
  (2081, 'navi', 'D', '그리스도를 첫자리에 모심', '마 6:33', '마 6:33', '마태복음 6장 33절', '그런즉 너희는 먼저 그의 나라와 그의 의를 구하라 그리하면 이 모든 것을 너희에게 더하시리라', null, true),
  (2082, 'navi', 'D', '그리스도를 첫자리에 모심', '눅 9:23', '눅 9:23', '누가복음 9장 23절', '또 무리에게 이르시되 아무든지 나를 따라오려거든 자기를 부인하고 날마다 제 십자가를 지고 나를 따를 것이니라', null, true),
  (2083, 'navi', 'D', '죄에서 떠남', '요일 2:15-16', '요일 2:15-16', '요한일서 2장 15-16절', '이 세상이나 세상에 있는 것들을 사랑하지 말라 누구든지 세상을 사랑하면 아버지의 사랑이 그 안에 있지 아니하니 이는 세상에 있는 모든 것이 육신의 정욕과 안목의 정욕과 이생의 자랑이니 다 아버지께로부터 온 것이 아니요 세상으로부터 온 것이라', null, true),
  (2084, 'navi', 'D', '죄에서 떠남', '롬 12:2', '롬 12:2', '로마서 12장 2절', '너희는 이 세대를 본받지 말고 오직 마음을 새롭게 함으로 변화를 받아 하나님의 선하시고 기뻐하시고 온전하신 뜻이 무엇인지 분별하도록 하라', null, true),
  (2085, 'navi', 'D', '견고함', '고전 15:58', '고전 15:58', '고린도전서 15장 58절', '그러므로 내 사랑하는 형제들아 견실하며 흔들리지 말고 항상 주의 일에 더욱 힘쓰는 자들이 되라 이는 너희 수고가 주 안에서 헛되지 않은 줄 앎이라', null, true),
  (2086, 'navi', 'D', '견고함', '히 12:3', '히 12:3', '히브리서 12장 3절', '너희가 피곤하여 낙심하지 않기 위하여 죄인들이 이같이 자기에게 거역한 일을 참으신 이를 생각하라', null, true),
  (2087, 'navi', 'D', '다른 사람을 섬김', '막 10:45', '막 10:45', '마가복음 10장 45절', '인자가 온 것은 섬김을 받으려 함이 아니라 도리어 섬기려 하고 자기 목숨을 많은 사람의 대속물로 주려 함이니라', null, true),
  (2088, 'navi', 'D', '다른 사람을 섬김', '고후 4:5', '고후 4:5', '고린도후서 4장 5절', '우리는 우리를 전파하는 것이 아니라 오직 그리스도 예수의 주 되신 것과 또 예수를 위하여 우리가 너희의 종 된 것을 전파함이라', null, true),
  (2089, 'navi', 'D', '후히 드릴 것', '잠 3:9-10', '잠 3:9-10', '잠언 3장 9-10절', '네 재물과 네 소산물의 처음 익은 열매로 여호와를 공경하라 그리하면 네 창고가 가득히 차고 네 포도즙 틀에 새 포도즙이 넘치리라', null, true),
  (2090, 'navi', 'D', '후히 드릴 것', '고후 9:6-7', '고후 9:6-7', '고린도후서 9장 6-7절', '이것이 곧 적게 심는 자는 적게 거두고 많이 심는 자는 많이 거둔다 하는 말이로다 각각 그 마음에 정한 대로 할 것이요 인색함으로나 억지로 하지 말지니 하나님은 즐겨 내는 자를 사랑하시느니라', null, true),
  (2091, 'navi', 'D', '세계 비전', '행 1:8', '행 1:8', '사도행전 1장 8절', '오직 성령이 너희에게 임하시면 너희가 권능을 받고 예루살렘과 온 유대와 사마리아와 땅 끝까지 이르러 내 증인이 되리라 하시니라', null, true),
  (2092, 'navi', 'D', '세계 비전', '마 28:19-20', '마 28:19-20', '마태복음 28장 19-20절', '그러므로 너희는 가서 모든 민족을 제자로 삼아 아버지와 아들과 성령의 이름으로 세례를 베풀고 내가 너희에게 분부한 모든 것을 가르쳐 지키게 하라 볼지어다 내가 세상 끝날까지 너희와 항상 함께 있으리라 하시니라', null, true),
  (2101, 'navi', 'E', '사랑', '요 13:34-35', '요 13:34-35', '요한복음 13장 34-35절', '새 계명을 너희에게 주노니 서로 사랑하라 내가 너희를 사랑한 것 같이 너희도 서로 사랑하라 너희가 서로 사랑하면 이로써 모든 사람이 너희가 내 제자인 줄 알리라', null, true),
  (2102, 'navi', 'E', '사랑', '요일 3:18', '요일 3:18', '요한일서 3장 18절', '자녀들아 우리가 말과 혀로만 사랑하지 말고 행함과 진실함으로 하자', null, true),
  (2103, 'navi', 'E', '겸손', '빌 2:3-4', '빌 2:3-4', '빌립보서 2장 3-4절', '아무 일에든지 다툼이나 허영으로 하지 말고 오직 겸손한 마음으로 각각 자기보다 남을 낫게 여기고 각각 자기 일을 돌볼뿐더러 또한 각각 다른 사람들의 일을 돌보아 나의 기쁨을 충만하게 하라', null, true),
  (2104, 'navi', 'E', '겸손', '벧전 5:5-6', '벧전 5:5-6', '베드로전서 5장 5-6절', '젊은 자들아 이와 같이 장로들에게 순종하고 다 서로 겸손으로 허리를 동이라 하나님은 교만한 자를 대적하시되 겸손한 자들에게는 은혜를 주시느니라 그러므로 하나님의 능하신 손 아래에서 겸손하라 때가 되면 너희를 높이시리라', null, true),
  (2105, 'navi', 'E', '순결', '엡 5:3', '엡 5:3', '에베소서 5장 3절', '음행과 온갖 더러운 것과 탐욕은 너희 중에서 그 이름조차도 부르지 말라 이는 성도에게 마땅한 바니라', null, true),
  (2106, 'navi', 'E', '순결', '벧전 2:11', '벧전 2:11', '베드로전서 2장 11절', '사랑하는 자들아 거류민과 나그네 같은 너희를 권하노니 영혼을 거슬러 싸우는 육체의 정욕을 제어하라', null, true),
  (2107, 'navi', 'E', '정직', '레 19:11', '레 19:11', '레위기 19장 11절', '너희는 도둑질하지 말며 속이지 말며 서로 거짓말하지 말며', null, true),
  (2108, 'navi', 'E', '정직', '행 24:16', '행 24:16', '사도행전 24장 16절', '이것으로 말미암아 나도 하나님과 사람에 대하여 항상 양심에 거리낌이 없기를 힘쓰나이다', null, true),
  (2109, 'navi', 'E', '믿음', '히 11:6', '히 11:6', '히브리서 11장 6절', '믿음이 없이는 하나님을 기쁘시게 하지 못하나니 하나님께 나아가는 자는 반드시 그가 계신 것과 또한 그가 자기를 찾는 자들에게 상 주시는 이심을 믿어야 할지니라', null, true),
  (2110, 'navi', 'E', '믿음', '롬 4:20-21', '롬 4:20-21', '로마서 4장 20-21절', '믿음이 없어 하나님의 약속을 의심하지 않고 믿음으로 견고하여져서 하나님께 영광을 돌리며 약속하신 그것을 또한 능히 이루실 줄을 확신하였으니', null, true),
  (2111, 'navi', 'E', '선행', '갈 6:9-10', '갈 6:9-10', '갈라디아서 6장 9-10절', '우리가 선을 행하되 낙심하지 말지니 포기하지 아니하면 때가 이르매 거두리라 그러므로 우리는 기회 있는 대로 모든 이에게 착한 일을 하되 더욱 믿음의 가정들에게 할지니라', null, true),
  (2112, 'navi', 'E', '선행', '마 5:16', '마 5:16', '마태복음 5장 16절', '이같이 너희 빛이 사람 앞에 비치게 하여 그들로 너희 착한 행실을 보고 하늘에 계신 너희 아버지께 영광을 돌리게 하라', null, true)
